    #: See https://debrid-link.fr/api_doc/v2
    API_URL = "https://debrid-link.fr/api/"

    def api_request(self, method, get={}, post={}, multipart=False):
        self.req.http.c.setopt(
            pycurl.HTTPHEADER, ["Authorization: Bearer " + self.api_token]
        )
        self.req.http.c.setopt(
            pycurl.USERAGENT, "pyLoad/{}".format(self.pyload.version)
        )
        try:
            json_data = self.load(self.API_URL + method, get=get, post=post, multipart=multipart)
        except BadHeader as exc:
            json_data = exc.content

        return json.loads(json_data)

    def api_request_safe(self, method, get={}, post={}, multipart=False):
        for _i in range(2):
            api_data = self.api_request(method, get=get, post=post, multipart=multipart)

            if "error" in api_data:
                if (
                    api_data["error"] == "badToken"
                ):  #: token expired, refresh the token and retry
                    self.account.relogin()
                    if not self.account.info["login"]["valid"]:
                        return api_data

                    else:
                        self.api_token = self.account.accounts[
                            list(self.account.accounts.keys())[0]
                        ]["api_token"]
                        continue

                else:
                    return api_data

            else:
                return api_data

    def sleep(self, sec):
        for _i in range(sec):
            if self.pyfile.abort:
                break
            time.sleep(1)

    def exit_error(self, msg):
        if self.tmp_file:
            os.remove(self.tmp_file)

        self.fail(msg)

    def send_request_to_server(self):
        """ Send torrent/magnet to the server """

        if self.pyfile.url.endswith(".torrent"):
            #: torrent URL
            if self.pyfile.url.startswith("http"):
                #: remote URL, send to the server
                api_data = self.api_request_safe(
                    "v2/seedbox/add",
                    post={
                        "url": self.pyfile.url,
                        "wait": True,
                        "async": True,
                    },
                )

            else:
                #: URL is local torrent file (uploaded container)
                torrent_filename = urllib.request.url2pathname(
                    self.pyfile.url[7:]
                )  #: trim the starting `file://`
                if not exists(torrent_filename):
                    self.fail(self._("Torrent file does not exist"))

                self.tmp_file = torrent_filename

                #: Check if the torrent file path is inside pyLoad's temp directory
                if os.path.abspath(torrent_filename).startswith(
                    self.pyload.tempdir + os.sep
                ):
                    #: send the torrent content to the server
                    api_data = self.api_request_safe(
                        "v2/seedbox/add",
                        post={
                            "file": FormFile(
                                torrent_filename, mimetype="application/x-bittorrent"
                            ),
                            "wait": True,
                            "async": True,
                        },
                        multipart=True,
                    )

                else:
                    self.exit_error(
                        self._("Illegal URL")
                    )  #: We don't allow files outside pyLoad's config directory

        else:
            #: magnet URL, send to the server
            api_data = self.api_request_safe(
                "v2/seedbox/add",
                post={"url": self.pyfile.url, "wait": True, "async": True},
            )

        if not api_data["success"]:
            self.exit_error(
                "{} (code: {})".format(
                    api_data.get(
                        "error_description", error_description(api_data["error"])
                    ),
                    api_data["error"],
                )
            )

        torrent_id = api_data["value"]["id"]

        self.pyfile.set_custom_status("metadata")
        self.pyfile.set_progress(0)

        #: Get the file list of the torrent
        page = 0
        files = []
        while True:
            api_data = self.api_request_safe(
                "v2/seedbox/list", get={"ids": torrent_id, "page": page, "perPage": 50}
            )

            if not api_data["success"]:
                self.exit_error(
                    "{} (code: {})".format(
                        api_data.get(
                            "error_description", error_description(api_data["error"])
                        ),
                        api_data["error"],
                    )
                )

            api_files = api_data["value"][0]["files"]
            if api_files:
                files.extend(
                    [
                        {
                            "id": _file["id"],
                            "name": _file["name"],
                            "size": _file["size"],
                            "url": _file["downloadUrl"],
                        }
                        for _file in api_files
                    ]
                )

                page = api_data["pagination"]["next"]
                if page == -1:
                    break

            self.sleep(5)

        self.pyfile.name = api_data["value"][0]["name"]

        #: Filter and select files for downloading
        exclude_filters = self.config.get("exclude_filter").split(";")
        excluded_ids = []
        for _filter in exclude_filters:
            excluded_ids.extend(
                [
                    _file["id"]
                    for _file in files
                    if fnmatch.fnmatch(_file["name"], _filter)
                ]
            )

        excluded_ids = uniquify(excluded_ids)

        include_filters = self.config.get("include_filter").split(";")
        included_ids = []
        for _filter in include_filters:
            included_ids.extend(
                [
                    _file["id"]
                    for _file in files
                    if fnmatch.fnmatch(_file["name"], _filter)
                ]
            )

        included_ids = uniquify(included_ids)

        selected_ids = [_id for _id in included_ids if _id not in excluded_ids]

        unwanted_ids = [
            _file["id"] for _file in files if _file["id"] not in selected_ids
        ]

        self.pyfile.size = sum(
            [_file["size"] for _file in files if _file["id"] in selected_ids]
        )

        api_data = self.api_request_safe(
            "v2/seedbox/{}/config".format(torrent_id),
            post={"files-unwanted": json.dumps(unwanted_ids)},
        )

        if not api_data["success"]:
            self.exit_error(
                "{} (code: {})".format(
                    api_data.get(
                        "error_description", error_description(api_data["error"])
                    ),
                    api_data["error"],
                )
            )

        return torrent_id, [
            _file["url"] for _file in files if _file["id"] in selected_ids
        ]

    def wait_for_server_dl(self, torrent_id):
        """ Show progress while the server does the download """

        self.pyfile.set_custom_status("torrent")
        self.pyfile.set_progress(0)

        while True:
            api_data = self.api_request_safe("v2/seedbox/activity", get={"ids": torrent_id})

            if not api_data["success"]:
                self.fail(
                    "{} (code: {})".format(
                        api_data.get(
                            "error_description",
                            api_data.get(
                                "error_description", error_description(api_data["error"])
                            ),
                        ),
                        api_data["error"],
                    )
                )

            if not api_data["value"]:
                self.fail("Torrent deleted from server")

            progress = int(api_data["value"][torrent_id]["downloadPercent"])
            self.pyfile.set_progress(progress)

            if progress == 100:
                break

            self.sleep(5)

        self.pyfile.set_progress(100)

    def delete_torrent_from_server(self, torrent_id):
        """ Remove the torrent from the server """
        url = "{}v2/seedbox/{}/remove".format(self.API_URL, torrent_id)
        self.log_debug("DELETE URL {}".format(url))
        c = pycurl.Curl()
        c.setopt(pycurl.URL, url)
        c.setopt(pycurl.SSL_VERIFYPEER, 0)
        c.setopt(pycurl.USERAGENT, "pyLoad/{}".format(self.pyload.version))
        c.setopt(
            pycurl.HTTPHEADER,
            [
                "Authorization: Bearer " + self.api_token,
                "Accept: */*",
                "Accept-Language: en-US,en",
                "Accept-Charset: ISO-8859-1,utf-8;q=0.7,*;q=0.7",
                "Connection: keep-alive",
                "Keep-Alive: 300",
                "Expect:",
            ],
        )
        c.setopt(pycurl.CUSTOMREQUEST, "DELETE")
        c.perform()
        code = c.getinfo(pycurl.RESPONSE_CODE)
        c.close()

        return code

    def decrypt(self, pyfile):
        self.tmp_file = None
        if "DebridlinkFr" not in self.pyload.account_manager.plugins:
            self.fail(self._("This plugin requires an active Debrid-slink.fr account"))

        self.account = self.pyload.account_manager.get_account_plugin("DebridlinkFr")
        if len(self.account.accounts) == 0:
            self.fail(self._("This plugin requires an active Debrid-slink.fr account"))

        self.api_token = self.account.accounts[list(self.account.accounts.keys())[0]][
            "api_token"
        ]

        torrent_id, torrent_urls = self.send_request_to_server()
        self.wait_for_server_dl(torrent_id)

        self.packages = [(pyfile.package().name, torrent_urls, pyfile.package().name)]

        if self.tmp_file:
            os.remove(self.tmp_file)

# -*- coding: utf-8 -*-

#
# Test links:
#   http://filecrypt.cc/Container/64E039F859.html

import base64
import re
import urllib.parse

from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

from pyload.core.network.cookie_jar import CookieJar
from pyload.core.network.http.exceptions import BadHeader
from pyload.core.network.http.http_request import HTTPRequest
from pyload.core.utils.convert import to_str

from ..anticaptchas.CoinHive import CoinHive
from ..anticaptchas.ReCaptcha import ReCaptcha
from ..anticaptchas.SolveMedia import SolveMedia
from ..base.decrypter import BaseDecrypter
from ..helpers import replace_patterns


class FilecryptCc(BaseDecrypter):
    __name__ = "FilecryptCc"
    __type__ = "decrypter"
    __version__ = "0.47"
    __status__ = "testing"

    __pattern__ = r"https?://(?:www\.)?filecrypt\.(?:cc|co)/Container/\w+"
    __config__ = [
        ("enabled", "bool", "Activated", True),
        ("handle_mirror_pages", "bool", "Handle Mirror Pages", True),
    ]

    __description__ = """Filecrypt.cc decrypter plugin"""
    __license__ = "GPLv3"
    __authors__ = [
        ("zapp-brannigan", "fuerst.reinje@web.de"),
        ("GammaC0de", "nitzo2001[AT]yahoo[DOT]com"),
    ]

    COOKIES = [("filecrypt.cc", "lang", "en")]
    URL_REPLACEMENTS = [(r"filecrypt.co", "filecrypt.cc")]

    DLC_LINK_PATTERN = r'onclick="DownloadDLC\(\'(.+)\'\);">'
    WEBLINK_PATTERN = r"<button onclick=\"openLink.?'([\w\-]*)',"
    MIRROR_PAGE_PATTERN = r'"[\w]*" href="(https?://(?:www\.)?filecrypt.cc/Container/\w+\.html\?mirror=\d+)">'

    CAPTCHA_PATTERN = r"<h2>Security prompt</h2>"
    INTERNAL_CAPTCHA_PATTERN = r'<img id="nc" .* src="(.+?)"'
    CIRCLE_CAPTCHA_PATTERN = r'<input type="image" src="(.+?)"'
    KEY_CAPTCHA_PATTERN = r"<script language=JavaScript src='(http://backs\.keycaptcha\.com/swfs/cap\.js)'"
    SOLVEMEDIA_CAPTCHA_PATTERN = r'<script type="text/javascript" src="(https?://api(?:-secure)?\.solvemedia\.com/papi/challenge.+?)"'

    def setup(self):
        self.urls = []

        try:
            self.req.http.close()
        except Exception:
            pass

        self.req.http = HTTPRequest(
            cookies=CookieJar(None),
            options=self.pyload.request_factory.get_options(),
            limit=2_000_000,
        )

    def decrypt(self, pyfile):
        pyfile.url = replace_patterns(pyfile.url, self.URL_REPLACEMENTS)

        self.data = self._filecrypt_load_url(pyfile.url)

        # @NOTE: "content notfound" is NOT a typo
        if (
            "content notfound" in self.data
            or ">File <strong>not</strong> found<" in self.data
        ):
            self.offline()

        self.handle_password_protection()

        self.site_with_links = self.handle_captcha(pyfile.url)
        if self.site_with_links is None:
            self.retry_captcha()

        elif self.site_with_links == "":
            self.retry()

        if self.config.get("handle_mirror_pages"):
            self.handle_mirror_pages()

        for handle in (
            self.handle_CNL,
            self.handle_weblinks,
            self.handle_dlc_container,
        ):
            handle()
            if self.urls:
                self.packages = [
                    (pyfile.package().name, self.urls, pyfile.package().name)
                ]
                return

    def handle_mirror_pages(self):
        if "mirror=" not in self.site_with_links:
            return

        mirror = re.findall(self.MIRROR_PAGE_PATTERN, self.site_with_links)

        self.log_info(self._("Found {} mirrors").format(len(mirror)))

        for i in mirror[1:]:
            self.site_with_links = self.site_with_links + self._filecrypt_load_url(i)

    def handle_password_protection(self):
        if (
            re.search(
                r'div class="input">\s*<input type="text" name="password" id="p4assw0rt"',
                self.data,
            )
            is None
        ):
            return

        self.log_info(self._("Folder is password protected"))

        password = self.get_password()

        if not password:
            self.fail(
                self._("Please enter the password in package section and try again")
            )

        self.data = self._filecrypt_load_url(
            self.pyfile.url, post={"password": password}
        )

    def handle_captcha(self, submit_url):
        if re.search(self.CAPTCHA_PATTERN, self.data):
            for handle in (
                self._handle_internal_captcha,
                self._handle_circle_captcha,
                self._handle_solvemedia_captcha,
                self._handle_keycaptcha_captcha,
                self._handle_coinhive_captcha,
                self._handle_recaptcha_captcha,
            ):

                res = handle(submit_url)
                if res is None:
                    continue

                elif res == "":
                    return res

                if re.search(self.CAPTCHA_PATTERN, res):
                    return None

                else:
                    return res

            else:
                self.log_warning(self._("Unknown captcha found, retrying"))
                return ""

        else:
            self.log_info(self._("No captcha found"))
            return self.data

    def _handle_internal_captcha(self, url):
        m = re.search(self.INTERNAL_CAPTCHA_PATTERN, self.data)
        if m is not None:
            captcha_url = urllib.parse.urljoin(self.pyfile.url, m.group(1))

            self.log_debug(f"Internal Captcha URL: {captcha_url}")

            captcha_code = self.captcha.decrypt(captcha_url, input_type="gif")

            return self._filecrypt_load_url(
                url, post={"recaptcha_response_field": captcha_code}
            )

        else:
            return None

    def _handle_circle_captcha(self, url):
        m = re.search(self.CIRCLE_CAPTCHA_PATTERN, self.data)
        if m is not None:
            self.log_debug(
                "Circle Captcha URL: {}".format(
                    urllib.parse.urljoin(self.pyfile.url, m.group(1))
                )
            )

            captcha_url = urllib.parse.urljoin(self.pyfile.url, m.group(1))

            self.log_debug(f"Circle Captcha URL: {captcha_url}")

            captcha_code = self.captcha.decrypt(
                captcha_url, input_type="png", output_type="positional"
            )

            return self._filecrypt_load_url(
                url, post={"button.x": captcha_code[0], "button.y": captcha_code[1]}
            )

        else:
            return None

    def _handle_solvemedia_captcha(self, url):
        m = re.search(self.SOLVEMEDIA_CAPTCHA_PATTERN, self.data)
        if m is not None:
            self.log_debug(
                "Solvemedia Captcha URL: {}".format(
                    urllib.parse.urljoin(self.pyfile.url, m.group(1))
                )
            )

            solvemedia = SolveMedia(self.pyfile)
            captcha_key = solvemedia.detect_key()

            if captcha_key:
                self.captcha = solvemedia
                response, challenge = solvemedia.challenge(captcha_key)

                return self._filecrypt_load_url(
                    url,
                    post={"adcopy_response": response, "adcopy_challenge": challenge},
                )

        else:
            return None

    def _handle_keycaptcha_captcha(self, url):
        m = re.search(self.KEY_CAPTCHA_PATTERN, self.data)
        if m is not None:
            self.log_debug(
                "Keycaptcha Captcha URL: {} unsupported, retrying".format(m.group(1))
            )
            return ""

        else:
            return None

    def _handle_coinhive_captcha(self, url):
        coinhive = CoinHive(self.pyfile)

        coinhive_key = coinhive.detect_key()
        if coinhive_key:
            self.captcha = coinhive
            token = coinhive.challenge(coinhive_key)

            return self._filecrypt_load_url(url, post={"coinhive-captcha-token": token})

        else:
            return None

    def _handle_recaptcha_captcha(self, url):
        recaptcha = ReCaptcha(self.pyfile)
        captcha_key = recaptcha.detect_key()

        if captcha_key:
            self.captcha = recaptcha
            response = recaptcha.challenge(captcha_key)

            return self._filecrypt_load_url(
                url, post={"g-recaptcha-response": response}
            )

        else:
            return None

    def handle_dlc_container(self):
        dlcs = re.findall(self.DLC_LINK_PATTERN, self.site_with_links)

        if not dlcs:
            return

        for dlc in dlcs:
            self.urls.append(
                urllib.parse.urljoin(self.pyfile.url, "/DLC/{}.dlc".format(dlc))
            )

    def handle_weblinks(self):
        try:
            links = re.findall(self.WEBLINK_PATTERN, self.site_with_links)

            for link in links:
                link = "http://www.filecrypt.cc/Link/{}.html".format(link)
                for i in range(5):
                    self.data = self._filecrypt_load_url(link)
                    m = re.search(r'https://www\.filecrypt\.cc/index\.php\?Action=Go&id=\w+', self.data)
                    if m is not None:
                        headers = self._filecrypt_load_url(m.group(0), just_header=True)
                        self.urls.append(headers["location"])
                        break

                else:
                    self.log_error(self._("Weblink could not be found"))

        except Exception as exc:
            self.log_debug(f"Error decrypting weblinks: {exc}")

    def handle_CNL(self):
        try:
            CNLdata = re.findall(
                r'onsubmit="CNLPOP\(\'(.*)\', \'(.*)\', \'(.*)\', \'(.*)\'\);',
                self.site_with_links,
            )
            for index in CNLdata:
                self.urls.extend(self._get_links(index[2], index[1]))

        except Exception as exc:
            self.log_debug(f"Error decrypting CNL: {exc}")

    def _get_links(self, crypted, jk):
        #: Get key and iv
        key = iv = bytes.fromhex(jk)

        #: Decrypt
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        decryptor = cipher.decryptor()
        text = to_str(
            decryptor.update(base64.b64decode(crypted)) + decryptor.finalize()
        )

        #: Extract links
        text = text.replace("\x00", "").replace("\r", "")
        links = [link for link in text.split("\n") if link]

        return links

    def _filecrypt_load_url(self, *args, **kwargs):
        try:
            return self.load(*args, **kwargs)
        except BadHeader as exc:
            if exc.code == 500:
                return exc.content
            else:
                raise

